css:
table {
    border-collapse: collapse;
}

tr.rowBorderLine{
    border-bottom: 1px solid #000000;
}
tr.rowBorderSolidLine{
    border-bottom: 2px solid #000;
}

td.columnBorder{
  border-left: 2px solid #000;
  border-right: 2px solid #000;
  border-top: 2px solid #000;
  border-bottom: 2px solid #000;
}

td.itemSI{
  text-align: left;
  width: 2%;
}

td.itemSKU{
  text-align: left;
  width: 10%;
}

td.itemITEMCODE{
  text-align: left;
  width: 10%;
}
td.itemBarcode{
  text-align: left;
  width: 10%;
}
td.itemBin{
  text-align: left;
  width: 27%;
}

td.itemExpiry{
  text-align: left;
  width: 6%;
}
td.itemDESCRIPTION{
  text-align: left;
  width: 25%;
}
td.itemUOM{
  text-align: left;
  width: 5%;
}
td.itemQTY{
  text-align: left;
  width: 5%;
}
td.itemBonusQTY{
  text-align: left;
  width: 5%;
}
td.itemUNITPRICE{
  text-align: left;
  width: 5%;
}
td.itemTotal{
  text-align: left;
  width: 5%;
}


.print-format .table-bordered td, .print-format .table-bordered th {
    border: 1px solid #000000!important;
    color: #000000;
}

